ui-polish.css:
/* Zero19: shared finishing layer. Keep this stylesheet after the feature styles. */
.app-shell{--surface-highlight:rgba(255,255,255,.045);--orange-line:rgba(255,126,65,.28);isolation:isolate}
.app-shell .topbar{border-bottom-color:#ffffff0b;background:linear-gradient(110deg,#101012ed,#101013e8 70%,#1f1510e8);box-shadow:0 5px 24px #0002}
.app-shell .nav-menu-trigger,.app-shell .top-back{border-color:#ffffff16;background:#ffffff05;transition:background .18s,border-color .18s}
.app-shell .nav-menu-trigger:hover,.app-shell .top-back:hover{border-color:#ff8d554c;background:#ff8d550b}
.app-shell .topbar .brand{cursor:pointer}
.app-shell :is(button,a,[role=button],input,select,textarea):focus-visible{outline:2px solid #ffad7b;outline-offset:3px}
.app-shell .simple-hero h1,.app-shell .dashboard-hero h1{letter-spacing:-.055em;line-height:1.1}
.app-shell .simple-hero p,.app-shell .dashboard-hero p{line-height:1.65}
.app-shell .eyebrow{font-size:10px;letter-spacing:.16em;color:#ff9257}
.app-shell :is(.workspace-card,.library-card,.share-link-card,.team-group,.queue-card){background:linear-gradient(155deg,#1c1c2180,#101014);border-color:#ffffff12;box-shadow:0 5px 25px #0002,inset 0 1px #ffffff03}
.app-shell .workspace-card:hover,.app-shell .library-card:hover{border-color:#ff8b454f;box-shadow:0 8px 28px #0004,inset 0 1px #ffffff06}
.app-shell .workspace-copy,.app-shell .workspace-copy h3,.app-shell .queue-card>div{min-width:0}
.app-shell .workspace-name-line h3,.app-shell .queue-card h2{overflow-wrap:anywhere}
.app-shell .btn{transition:background .16s,border-color .16s,transform .16s,box-shadow .16s}
.app-shell .btn.primary{background:linear-gradient(135deg,#ff8844,#ff621f);box-shadow:inset 0 1px #ffb88f4d,0 3px 14px #ff68130b}
.app-shell .btn.primary:hover{background:linear-gradient(135deg,#ff9a5f,#ff7231);box-shadow:0 5px 20px #ff681321}
.app-shell .operation-launcher{border-color:#ff8b4536;background:radial-gradient(ellipse at 0 0,#ff742914,transparent 65%),linear-gradient(145deg,#17161a,#111115);box-shadow:0 12px 35px #0002,inset 0 1px #ffc69e0b}
.app-shell .operation-action{position:relative;overflow:hidden;background:linear-gradient(135deg,#212024,#18171c);border-color:#ffffff0f}
.app-shell .operation-action:after{content:'↗';position:absolute;right:18px;top:17px;font-size:21px;color:#82756d}
.app-shell .operation-action:hover:after{color:#ffba8b}
.app-shell .operation-action>span{background:linear-gradient(145deg,#ff954f,#ff6924);box-shadow:0 4px 13px #ff7d2421}
.app-shell .queue-scope{border-color:#ffffff10;background:#08080b80}
.app-shell .queue-scope button.active{background:linear-gradient(140deg,#ff8a49,#ff6927)}
.app-shell .film-controls{background:linear-gradient(140deg,#1e1c1e,#151419);border-color:#ffffff14;padding:19px;border-radius:20px}
.app-shell .film-controls input,.app-shell .film-controls select{border-color:#ffffff17;background:#101014;min-width:0}
.app-shell .film-workspace>aside,.app-shell .film-workspace>div{background:linear-gradient(160deg,#1a191de8,#111115);border-color:#ffffff12;border-radius:20px}
.app-shell .film-workspace h2{font-size:17px;letter-spacing:-.03em;margin:2px 0 16px}
.app-shell .film-preview-shell{border:1px solid #ffffff0d;background:radial-gradient(ellipse at top,#201c1b40,transparent 70%),#0b0b0e}
.app-shell .film-item{gap:10px;align-items:center;border-color:#ffffff0b}
.app-shell .film-item>div{min-width:0}
.app-shell .film-item b{font-size:12px;line-height:1.45;overflow-wrap:anywhere}
.app-shell .film-item small{font-size:10px;line-height:1.5;color:#a3a0aa}
.app-shell .film-item>.btn{flex:0 0 auto}
.app-shell .film-metrics span{border:1px solid #ffffff09;background:#0b0b0e9c}
.app-shell .film-metrics b{color:#f7d0b8}
.app-shell .film-metrics small{font-size:9px;line-height:1.4}
.app-shell .asset-card.clean{border-color:#ffffff14;background:linear-gradient(145deg,#1a191f,#111114);transition:border-color .15s,box-shadow .15s}
.app-shell .asset-card.clean:hover{border-color:#bb764553;box-shadow:0 6px 24px #0003}
.app-shell .asset-actions{flex-wrap:wrap}
.app-shell .asset-actions .btn{min-width:0;flex:1 1 auto}
.app-shell .asset-card :is(.missing-size,.ready-size){line-height:1.5;padding:5px 8px;border-radius:7px}
.app-shell .sidebar{border-color:#ffffff12;background:linear-gradient(165deg,#18171c,#111115)}
.app-shell .folder.active{background:linear-gradient(90deg,#ff8b4514,#ff8b4505);color:#ffba91;box-shadow:inset 3px 0 #ff8543}
.app-shell .app-drawer{background:radial-gradient(ellipse at top left,#42221665,transparent 65%),linear-gradient(160deg,#151519,#0b0b0e);box-shadow:20px 0 100px #0009;border-color:#d8a98b21}
.app-shell .drawer-section .active{background:#ff8d4510;border-color:#ff8d452b;box-shadow:inset 3px 0 #ff8842}
.app-shell .drawer-section small{color:#988580;letter-spacing:.13em}
#toast-root{z-index:250}
@media(hover:hover){.app-shell .btn:not(:disabled):active{transform:translateY(0)}.app-shell .operation-action:hover{transform:translateY(-2px)}}
@media(min-width:1100px){.app-shell>.container{padding-top:32px}.app-shell .simple-hero{margin-bottom:23px}.app-shell .dashboard-hero{margin-bottom:17px}}
@media(max-width:980px){.app-shell .film-controls{padding:15px}.app-shell .film-workspace{gap:13px}.app-shell .toolbar>.search{min-width:min(240px,100%)}}
@media(max-width:760px){
