  .mobile-bottom-nav{position:fixed;z-index:45;left:10px;right:10px;bottom:calc(10px + env(safe-area-inset-bottom,0px));height:69px;padding:7px 5px;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:2px;border:1px solid #c8b6ac26;border-radius:23px;background:radial-gradient(ellipse at 48% 0,#b0572f19,transparent 70%),linear-gradient(130deg,#222126f0,#131317f2);backdrop-filter:blur(26px) saturate(145%);-webkit-backdrop-filter:blur(26px) saturate(145%);box-shadow:0 8px 28px #0009,0 2px 8px #0005,inset 0 1px #ffffff10;overflow:visible}
